import { test, expect } from '@playwright/test';

test.describe('Checkout Flow', () => {
  test('should complete the checkout process successfully', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.login('standard_user', 'secret_sauce');
    await page.click('a[data-test="add-to-cart-sauce-labs-backpack"]');
    await page.click('a[data-test="checkout"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('a[data-test="continue"]')).toBeVisible();
    await expect(page.locator('a[data-test="finish"]')).toBeVisible();
    await page.click('a[data-test="continue"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('a[data-test="finish"]')).toBeVisible();
    await page.click('a[data-test="finish"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('a[data-test="continue"]')).toBeVisible();
    await expect(page.locator('a[data-test="finish"]')).toBeVisible();
  });

  test('should not change the URL after clicking the cart link', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.click('a[data-test="checkout"]');
    await expect(page).toHaveURL(/.*saucedemo.com/);
    await expect(page.locator('a[data-test="continue"]')).toBeVisible();
    await expect(page.locator('a[data-test="finish"]')).toBeVisible();
  });
});
